const RECIPLOG_LOOKUP_BITS: i32 = 9;
const RECIPLOG_LOOKUP_PREC: i32 = 22;
const RECIPLOG_INPUT_PREC: i32 = 32;
const RECIP_OUTPUT_PREC: i32 = 15;
const LOG_OUTPUT_PREC: i32 = 8;

/// `fast_reciplog` — the reciprocal of `value` plus `log2(1/value)`, both by
/// table lookup and linear interpolation. Integer only, as in the C.
pub fn fast_reciplog(value: i64, log_2: &mut i32) -> i64 {
    let neg = value < 0;
    let value = if neg { -value } else { value };

    // Spilled out of 32 bits: push it down and remember the shift.
    let (mut temp, mut exponent) = if value & 0xffff_0000_0000u64 as i64 != 0 {
        ((value >> 16) as u32, -16i32)
    } else {
        (value as u32, 0i32)
    };

    // A zero value has an infinite reciprocal.
    if temp == 0 {
        *log_2 = 1000 << LOG_OUTPUT_PREC;
        return if neg { 0x8000_0000 } else { 0x7fff_ffff };
    }

    let lz = temp.leading_zeros() as i32;
    temp <<= lz;
    exponent += lz;

    // Two u32 per entry, hence the one-short shift and the even mask.
    let idx = ((temp >> (31 - RECIPLOG_LOOKUP_BITS - 1))
        & ((2u32 << RECIPLOG_LOOKUP_BITS) - 2)) as usize;
    let interp = ((temp >> (31 - RECIPLOG_LOOKUP_BITS - 8)) & 0xff) as u64;

    let t = &RECIPLOG[idx..idx + 4];
    let rlog = ((t[1] as u64 * (0x100 - interp) + t[3] as u64 * interp) >> 8) as u32;
    let recip = (t[0] as u64 * (0x100 - interp) + t[2] as u64 * interp) >> 8;

    // The log result is the fraction; round it to the output precision. The
    // exponent is the integer part, and since we want log(1/value) the log is
    // subtracted FROM it rather than the other way round.
    let rlog = (rlog + (1 << (RECIPLOG_LOOKUP_PREC - LOG_OUTPUT_PREC - 1)))
        >> (RECIPLOG_LOOKUP_PREC - LOG_OUTPUT_PREC);
    *log_2 = ((exponent - (31 - RECIPLOG_INPUT_PREC)) << LOG_OUTPUT_PREC) - rlog as i32;

    // Fold every reciprocal-related precision into one shift.
    exponent += (RECIP_OUTPUT_PREC - RECIPLOG_LOOKUP_PREC) - (31 - RECIPLOG_INPUT_PREC);
    let recip = if exponent < 0 {
        recip >> -exponent
    } else {
        recip << exponent
    } as i64;

    if neg { -recip } else { recip }
}
